<?php
declare(strict_types=1);
namespace AM2050\Controllers;
use AM2050\Core\Request; use AM2050\Core\Response; use AM2050\Middleware\AuthMiddleware; use AM2050\Middleware\RoleMiddleware; use AM2050\Services\ChildService;
final class ChildController { public function __construct(private readonly AuthMiddleware $auth,private readonly ChildService $service){} private function registryActor(Request $request):array{$actor=$this->auth->require($request);RoleMiddleware::allow($actor,['super_admin','program_admin','lga_supervisor','ward_supervisor','mobilizer']);return $actor;} private function schoolReadActor(Request $request):array{$actor=$this->auth->require($request);RoleMiddleware::allow($actor,['super_admin','program_admin','lga_supervisor','ward_supervisor','headmaster','mobilizer','teacher']);return $actor;} private function guardianActor(Request $request):array{$actor=$this->auth->require($request);RoleMiddleware::allow($actor,['super_admin','program_admin','lga_supervisor','ward_supervisor','mobilizer']);return$actor;} public function list(Request $request):never{$actor=$this->schoolReadActor($request);$result=$this->service->list($actor,$request->query);Response::paginate($result['data'],$result['page'],$result['limit'],$result['total']);} public function get(Request $request,array $params):never{Response::success($this->service->get($this->schoolReadActor($request),$params['id']));} public function create(Request $request):never{Response::success($this->service->create($this->registryActor($request),$request->body()),201);} public function update(Request $request,array $params):never{Response::success($this->service->update($this->registryActor($request),$params['id'],$request->body()));} public function confirmGuardian(Request $request,array $params):never{Response::success($this->service->confirmGuardianPhone($this->guardianActor($request),$params['id'],$request->body()));} }
